<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class StoreTransportVehicleRequest extends FormRequest {public function authorize():bool{return $this->user()?->can('transporte.vehiculos.gestionar')??false;}public function rules():array{$company=$this->user()->company_id;$id=$this->route('vehicle')?->id;return['plate'=>['required','string','max:20',Rule::unique('transport_vehicles')->where(fn($q)=>$q->where('company_id',$company))->ignore($id)],'internal_code'=>['nullable','string','max:50',Rule::unique('transport_vehicles')->where(fn($q)=>$q->where('company_id',$company))->ignore($id)],'vehicle_type'=>['required',Rule::in(array_keys(config('transport.vehicle_types')))],'brand'=>'nullable|string|max:80','model'=>'nullable|string|max:80','year'=>'nullable|integer|min:1950|max:'.(date('Y')+1),'capacity'=>'required|integer|min:1|max:200','owner_type'=>['required',Rule::in(array_keys(config('transport.owner_types')))],'owner_name'=>'nullable|required_unless:owner_type,company|string|max:255','status'=>'required|in:active,inactive','notes'=>'nullable|string|max:2000'];}}
